import { parentPort } from 'node:worker_threads';

// Receives { buffer } via postMessage. In copy mode the buffer is a
// structured-clone snapshot; in transfer mode it is the same memory,
// zero-copied (sender's buffer is detached).
parentPort.on('message', ({ buffer }) => {
  const arr = new Float64Array(buffer);
  for (let i = 0; i < arr.length; i++) {
    arr[i] *= 2;
  }
  // Send it back, transferring ownership to avoid a copy on the return leg.
  parentPort.postMessage({ buffer }, [buffer]);
});

