import { Worker } from 'node:worker_threads';
import { writeFileSync } from 'node:fs';

const N = 8_000_000;
const ITERATIONS = 5;

function makeData() {
  return Float64Array.from({ length: N }, (_, i) => i + 1);
}

async function roundTrip(mode) {
  const data = makeData();
  const transferList = mode === 'transfer' ? [data.buffer] : [];
  const worker = new Worker(new URL('./double_worker.mjs', import.meta.url));

  const start = performance.now();
  worker.postMessage({ buffer: data.buffer }, transferList);
  const { buffer } = await new Promise((resolve, reject) => {
    worker.once('message', resolve);
    worker.once('error', reject);
  });
  const elapsed = performance.now() - start;
  await worker.terminate();

  // Sanity check: values doubled.
  const out = new Float64Array(buffer);
  if (out[N - 1] !== 2 * N) throw new Error('bad result');
  return elapsed;
}

const copyTimes = [];
const transferTimes = [];

for (let i = 0; i < ITERATIONS; i++) {
  copyTimes.push(await roundTrip('copy'));
  transferTimes.push(await roundTrip('transfer'));
}

const median = (xs) => xs.slice().sort((a, b) => a - b)[Math.floor(xs.length / 2)];
const copy_ms = median(copyTimes);
const transfer_ms = median(transferTimes);
const report = {
  copy_ms: +copy_ms.toFixed(3),
  transfer_ms: +transfer_ms.toFixed(3),
  ratio: +(copy_ms / transfer_ms).toFixed(3),
};

writeFileSync(new URL('./transfer_report.json', import.meta.url), JSON.stringify(report, null, 2));
console.log('copy     runs:', copyTimes.map((t) => t.toFixed(1)).join(', '), 'ms');
console.log('transfer runs:', transferTimes.map((t) => t.toFixed(1)).join(', '), 'ms');
console.log(report);

