import test from 'node:test';
import assert from 'node:assert/strict';
import { Worker } from 'node:worker_threads';

const N = 8_000_000;

function makeData() {
  return Float64Array.from({ length: N }, (_, i) => i + 1);
}

function roundTrip(mode) {
  const data = makeData();
  const transferList = mode === 'transfer' ? [data.buffer] : [];
  return new Promise((resolve, reject) => {
    const worker = new Worker(new URL('./double_worker.mjs', import.meta.url));
    worker.once('message', ({ buffer }) => {
      worker.terminate().finally(() => resolve({ buffer, sender: data }));
    });
    worker.once('error', reject);
    worker.postMessage({ buffer: data.buffer }, transferList);
  });
}

test('copy mode: values are numerically correct', async () => {
  const { buffer } = await roundTrip('copy');
  const out = new Float64Array(buffer);
  assert.equal(out.length, N);
  for (let i = 0; i < N; i++) {
    assert.equal(out[i], (i + 1) * 2);
  }
});

test('transfer mode: values are numerically correct', async () => {
  const { buffer } = await roundTrip('transfer');
  const out = new Float64Array(buffer);
  assert.equal(out.length, N);
  // Spot-check plus full pass.
  for (let i = 0; i < N; i++) {
    assert.equal(out[i], (i + 1) * 2);
  }
});

test('transfer mode: sender buffer is detached (byteLength 0)', async () => {
  const { sender } = await roundTrip('transfer');
  assert.equal(sender.buffer.byteLength, 0);
});

test('copy mode: sender buffer is NOT detached', async () => {
  const { sender } = await roundTrip('copy');
  assert.equal(sender.buffer.byteLength, N * 8);
});

test('transfer beats copy', async () => {
  const report = JSON.parse(
    await import('node:fs').then((fs) => fs.readFileSync(new URL('./transfer_report.json', import.meta.url), 'utf8'))
  );
  assert.ok(report.transfer_ms < report.copy_ms,
    `expected transfer (${report.transfer_ms}ms) < copy (${report.copy_ms}ms)`);
  assert.ok(report.ratio > 1);
});

